/**
 * @file PokemonDB.js
 * @brief Read-only repository of the Pokémon species and their forms (C++: class PokemonDB : public DataRepository).
 * Built from data/raw/species-data.js and data/raw/forms-data.js (generated by tools/data/).
 * Species are keyed by slug ('mr-mime'); the National Pokédex number is only an attribute.
 */
import { DataRepository } from '../core/DataRepository.js';
import { SPECIES_TABLE as GENERATED_SPECIES } from '../raw/species-data.js';
import { FORMS_TABLE as GENERATED_FORMS } from '../raw/forms-data.js';
import { SPECIES_CONTENT } from '../content/species-content.js';
import { FORMS_CONTENT } from '../content/forms-content.js';
import { withContent } from '../core/ContentTables.js';

const SPECIES_TABLE = withContent(GENERATED_SPECIES, SPECIES_CONTENT);
const FORMS_TABLE = withContent(GENERATED_FORMS, FORMS_CONTENT);
import { PokemonSpecies } from './PokemonSpecies.js';
import { PokemonForm } from './PokemonForm.js';
import { TypeChart } from '../core/TypeChart.js';
import { REGIONS } from '../../config/Regions.js';
import { TalentDB } from './TalentDB.js';

export class PokemonDB extends DataRepository {
  /** @type {PokemonDB|null} */
  static _instance = null;

  /** @returns {PokemonDB} */
  static getInstance() {
    if (!PokemonDB._instance) PokemonDB._instance = new PokemonDB();
    return PokemonDB._instance;
  }

  constructor() {
    super('PokemonDB');
  }

  /** @protected @override */
  _build() {
    /** @private @type {Map<number, PokemonSpecies>} */
    this._byDex = new Map();
    /** @private @type {Map<string, PokemonForm>} */
    this._forms = new Map();
    for (const [id, raw] of Object.entries(SPECIES_TABLE)) {
      const species = new PokemonSpecies(id, raw);
      this._entries.set(id, species);
      this._byDex.set(species.dex, species);
    }
    for (const [id, raw] of Object.entries(FORMS_TABLE)) {
      const form = new PokemonForm(id, raw);
      this._forms.set(id, form);
      const species = this._entries.get(form.species);
      if (species) species.forms.push(form);
    }
    for (const species of this._entries.values()) {
      Object.freeze(species.forms);
      Object.freeze(species);
    }
  }

  /**
   * @param {number} dex - National Pokédex number (only for original-save migration and sorting)
   * @returns {PokemonSpecies|null}
   */
  getByDex(dex) {
    return this._byDex.get(Number(dex)) || null;
  }

  /**
   * @param {string} region - Regions id
   * @returns {PokemonSpecies[]} In Pokédex order
   */
  getByRegion(region) {
    return this.getAll().filter((species) => species.region === region);
  }

  /**
   * @param {string} formId - '<species>_<form>'
   * @returns {PokemonForm|null}
   */
  getForm(formId) {
    return this._forms.get(formId) || null;
  }

  /** @returns {PokemonForm[]} */
  getAllForms() {
    return [...this._forms.values()];
  }

  /**
   * Types and base stats of a species, or of one of its forms.
   * @param {string} speciesId
   * @param {string} [formKey=''] - Form suffix ('sunny'); empty for the base form
   * @returns {PokemonSpecies|PokemonForm|null}
   */
  getVariant(speciesId, formKey = '') {
    const species = this.getById(speciesId);
    if (!species) return null;
    return (formKey && species.getForm(formKey)) || species;
  }

  /** @override */
  validate() {
    const problems = [];
    const regionIds = REGIONS.map((region) => region.id);
    const talents = TalentDB.getInstance();
    for (const species of this._entries.values()) {
      if (!regionIds.includes(species.region)) problems.push(this._problem(species.id, 'region', species.region));
      for (const type of species.types) {
        if (!TypeChart.normalize(type)) problems.push(this._problem(species.id, 'types', type));
      }
      for (const evolution of species.evolutions) {
        if (!this.has(evolution.to)) problems.push(this._problem(species.id, 'evolutions', evolution.to));
      }
      if (species.talents.length === 0) problems.push(this._problem(species.id, 'talents', null));
      for (const talent of [...species.talents, ...(species.hiddenTalent ? [species.hiddenTalent] : [])]) {
        if (!talents.has(talent)) problems.push(this._problem(species.id, 'talents', talent));
      }
    }
    for (const form of this._forms.values()) {
      if (!this.has(form.species)) problems.push(this._problem(form.id, 'species', form.species));
    }
    return problems;
  }
}
